<?php require __DIR__ . '/data/pets.php'; $page = 'adopt'; $selected = (int) ($_GET['pet'] ?? 1); ?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Start Adoption | Paw &amp; Home</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/styles.css"></head><body><?php require __DIR__ . '/includes/header.php'; ?><main class="page-shell"><section class="page-heading"><span class="kicker">Take the first step / intake form</span><h1>Tell us about your home.</h1><p>This short demo form helps a caregiver understand whether the match could be a good fit.</p></section><section class="two-column"><section class="form-panel"><form id="adoption-form"><label>Pet you are interested in<select id="pet-select" name="pet" required><?php foreach ($pets as $pet) echo '<option value="' . $pet['id'] . '"' . ($pet['id'] === $selected ? ' selected' : '') . '>' . htmlspecialchars($pet['name'] . ' · ' . $pet['breed']) . '</option>'; ?></select></label><div class="form-grid"><label>Your name<input name="name" required placeholder="Full name"></label><label>Email<input name="email" type="email" required placeholder="you@example.com"></label><label>City<input name="city" required placeholder="Where do you live?"></label><label>Home type<select name="home" required><option value="">Choose one</option><option>Apartment</option><option>House with yard</option><option>House without yard</option></select></label></div><label>Tell us about your routine<textarea name="message" required placeholder="What would a normal day look like for this pet?"></textarea></label><button class="button button-pink" type="submit">Send adoption request</button></form><div id="